/** UC-9 selected edits, exact native fidelity, deliberate grouping and atomic responsibility transfer. */
class DefinitionOccurrencesBrowserIT extends WorkbenchBrowserSupport {
    @Test
    void browserEveryFieldCancelInheritanceNavigationReloadRestartAndHandoffs() {
        initial(false);open();nav("Weekly requirements");page().locator("#customize-requirement-occurrences").click();form();
        JsonNode source=draft().path("sourceDocument").deepCopy(),unrelated=lesson("lesson-science-1").deepCopy();
        value("displayName","Erand õppetund");value("teacherId","teacher-blair");value("requiredRoomCapabilityIds","lab, Exact.Token_9");value("preferredRoomIds","");value("undesirablePeriodIds","mon-3");value("periodLock","mon-2");value("roomLock","room-101");
        String before=storedDocument();preview();workbench.awaitText("Explicit exception");page().locator("#cancel-occurrence-review").click();assertEquals(before,storedDocument());assertEquals("Erand õppetund",page().locator("#occurrence-displayName").inputValue());save();
        JsonNode row=lesson("lesson-math-1");assertEquals("Erand õppetund",row.path("displayName").asString());assertEquals("teacher-blair",row.path("teacherId").asString());assertEquals(JSON.readTree("[\"lab\",\"Exact.Token_9\"]"),row.path("requiredRoomCapabilityIds"));assertEquals(JSON.readTree("[]"),row.path("preferredRoomIds"));assertEquals("mon-2",row.path("periodLock").asString());assertEquals("room-101",row.path("roomLock").asString());assertEquals(11,row.size());assertEquals(unrelated,lesson("lesson-science-1"));assertEquals(source,draft().path("sourceDocument"));assertEquals("mon-2",draft().path("editingContext").path("authoredLocks").path("lesson-math-1").path("periodLock").asString());
        page().locator("#occurrence-teacherId-mode").selectOption("inherit");page().locator("#occurrence-periodLock-mode").selectOption("omitted");save();assertEquals("teacher-alex",lesson("lesson-math-1").path("teacherId").asString());assertFalse(lesson("lesson-math-1").has("periodLock"));assertFalse(context("series-math-7a").path("exceptions").path("lesson-math-1").toString().contains("teacherId"));
        value("displayName","Working only");nav("Review");page().locator("#school-stay").click();assertEquals("Working only",page().locator("#occurrence-displayName").inputValue());nav("Review");page().locator("#school-discard-working").click();assertEquals("Erand õppetund",lesson("lesson-math-1").path("displayName").asString());nav("Teachers");page().locator("#reassign-teacher-occurrences").click();form();assertTrue(page().locator("input[aria-label^='Select occurrence:']").first().isChecked());
        value("subjectId","science");value("cohortId","cohort-7a");save();assertEquals("science",lesson("lesson-math-1").path("subjectId").asString());assertFalse(lesson("lesson-math-1").has("seriesId"));assertEquals(0,context("series-math-7a").path("count").intValue());
        String saved=storedDocument();workbench.reload();nav("Occurrence details");form();assertEquals(saved,storedDocument());try(var restarted=startRestartableWorkspace()){int p=((org.springframework.boot.web.server.context.WebServerApplicationContext)restarted).getWebServer().getPort();workbench.open(p);nav("Occurrence details");form();assertEquals(saved,storedDocument());}
    }

    @Test
    void mixedInheritanceExplicitEqualExceptionGroupingAndUnrelatedIncompleteContext() {
        initial(true);open();nav("Occurrence details");form();ObjectNode op=operation("lesson-math-1");mode(op,"teacherId","inherit");String before=storedDocument();assertEquals(409,previewCommand(op).status());assertEquals(before,storedDocument());
        op=operation("lesson-math-1");change(op,"teacherId","teacher-alex");assertEquals(200,saveCommand(op).status());assertTrue(context("series-math-7a").path("exceptions").path("lesson-math-1").toString().contains("teacherId"));assertEquals("teacher-blair",lesson("imported.math.2").path("teacherId").asString());
        ObjectNode requirement=JSON.createObjectNode().put("originalSeriesId","series-math-7a").put("seriesId","series-math-7a").put("cohortId","cohort-7a").put("subjectId","math").put("count",2);requirement.putObject("changes").putObject("teacherId").put("mode","value").put("value","teacher-blair");requirement.putObject("followers");requirement.putArray("applyToAllFields").add("teacherId");requirement.putArray("removeIds");APIResponse rp=post("/api/definition-draft/requirements/preview",requirement,null);assertEquals(200,rp.status());ObjectNode env=JSON.createObjectNode().put("token",JSON.readTree(rp.text()).path("token").asString());env.set("request",requirement);assertEquals(200,post("/api/definition-draft/requirements",env,null).status());
        op=operation("lesson-math-1");change(op,"teacherId","teacher-blair");assertEquals(200,saveCommand(op).status());assertTrue(context("series-math-7a").path("exceptions").path("lesson-math-1").toString().contains("teacherId"));op=operation("lesson-math-1");mode(op,"teacherId","inherit");assertEquals(200,saveCommand(op).status());assertFalse(context("series-math-7a").path("exceptions").path("lesson-math-1").toString().contains("teacherId"));
        JsonNode science=lesson("lesson-science-1").deepCopy();op=operation("lesson-science-1");op.withObject("grouping").put("mode","existing").put("seriesId","series-math-7a");before=storedDocument();assertEquals(409,previewCommand(op).status());assertEquals(before,storedDocument());
        op=operation("lesson-math-1","imported.math.2");op.withObject("grouping").put("mode","new").put("seriesId","New.Series_9");assertEquals(200,saveCommand(op).status());assertEquals(0,context("series-math-7a").path("count").intValue());assertEquals(2,context("New.Series_9").path("count").intValue());assertEquals(science,lesson("lesson-science-1"));
        op=operation("lesson-math-1");op.withObject("grouping").put("mode","detach");assertEquals(200,saveCommand(op).status());assertFalse(lesson("lesson-math-1").has("seriesId"));assertEquals(1,context("New.Series_9").path("count").intValue());op=operation("lesson-math-1");op.withObject("grouping").put("mode","existing").put("seriesId","New.Series_9");assertEquals(200,saveCommand(op).status());assertEquals("New.Series_9",lesson("lesson-math-1").path("seriesId").asString());
        ObjectNode doc=((ObjectNode)storedWorkspaceDocument()).deepCopy();doc.withObject("definitionDraft").withObject("editingContext").withObject("requirements").withObject("series-math-7a").put("count","unfinished");store("DEFINITION_DRAFT",doc);JsonNode incomplete=context("series-math-7a").deepCopy();op=operation("lesson-math-1");change(op,"displayName","Stable identity");assertEquals(200,saveCommand(op).status());assertEquals(incomplete,context("series-math-7a"));assertEquals("lesson-math-1",lesson("lesson-math-1").path("id").asString());
    }

    @Test
    void selectedTeachingAndExplicitScopedRuleTransferNeverGrantQualifications() {
        initial(true);open();nav("Occurrence details");form();JsonNode before=definition().deepCopy(),source=draft().path("sourceDocument").deepCopy();ObjectNode op=operation("lesson-math-1");change(op,"teacherId","unknown-teacher");assertEquals(200,saveCommand(op).status());assertEquals(before.path("teachers"),definition().path("teachers"));assertEquals(before.path("roomAssignments"),definition().path("roomAssignments"));assertEquals(before.path("lessons").get(2),lesson("imported.math.2"));assertTrue(draft().path("issues").toString().contains("teacherId"));
        op=operation("lesson-math-1");change(op,"teacherId","teacher-alex");assertEquals(200,saveCommand(op).status());op=operation("lesson-math-1");change(op,"teacherId","teacher-blair");op.withArray("transferRuleIds").add("math-alex");JsonNode preview=JSON.readTree(previewCommand(op).text());assertEquals("teacher-alex",preview.path("rulesBefore").get(0).path("teacherId").asString());assertEquals("teacher-blair",preview.path("rulesAfter").get(0).path("teacherId").asString());assertEquals(200,saveCommand(op).status());assertEquals("teacher-blair",definition().path("roomAssignments").get(0).path("teacherId").asString());assertEquals(before.path("teachers"),definition().path("teachers"));assertEquals(source,draft().path("sourceDocument"));
        op=operation("lesson-science-1");change(op,"teacherId","teacher-blair");op.withArray("transferRuleIds").add("math-alex");String unchanged=storedDocument();assertEquals(409,previewCommand(op).status());assertEquals(unchanged,storedDocument());op=operation("lesson-math-1");op.withArray("transferRuleIds").add("math-alex");assertEquals(409,previewCommand(op).status());assertEquals(unchanged,storedDocument());
        op=operation("lesson-math-1");change(op,"teacherId","unknown-teacher");op.withArray("transferRuleIds").add("math-alex");assertEquals(200,saveCommand(op).status());assertTrue(draft().path("issues").toString().contains("ROOM_POLICY_FIELDS"));ObjectNode teacher=JSON.createObjectNode().put("id","unknown-teacher").put("displayName","Corrected teacher");teacher.putArray("qualifiedSubjectIds").add("math");ObjectNode add=JSON.createObjectNode().put("originalId","");add.set("item",teacher);assertEquals(200,post("/api/definition-draft/teachers",add,null).status());assertFalse(draft().path("issues").toString().contains("ROOM_POLICY_FIELDS"));
    }

    @Test
    void staleStorageTransportSelectionResponsiveAndStateGuardsCommitNoSubset() throws Exception {
        storeAccepted(fixtures.validAcceptedDocument());workbench.open();open();nav("Occurrence details");form();JsonNode source=draft().path("sourceDocument").deepCopy();ObjectNode op=operation("lesson-math-1");change(op,"displayName","Stale");JsonNode preview=JSON.readTree(previewCommand(op).text());assertEquals(1,preview.path("sourcePlacements").size());ObjectNode newer=operation("lesson-math-1");change(newer,"displayName","Newer");assertEquals(200,saveCommand(newer).status());String unchanged=storedDocument();ObjectNode env=JSON.createObjectNode().put("token",preview.path("token").asString());env.set("request",op);assertEquals(409,post("/api/definition-draft/occurrences",env,null).status());assertEquals(unchanged,storedDocument());workbench.reload();nav("Occurrence details");form();value("displayName","Working");
        page().locator("input[aria-label^='Select occurrence:']").last().click();page().locator("#school-stay").click();assertFalse(page().locator("input[aria-label^='Select occurrence:']").last().isChecked());assertEquals("Working",page().locator("#occurrence-displayName").inputValue());
        for(int width:List.of(1600,1280,390,700)){workbench.viewport(width,844);workbench.expect("document.documentElement.scrollWidth <= innerWidth");assertEquals(unchanged,storedDocument());if(width<=700)assertEquals(0,page().locator("#occurrence-form").count());}workbench.viewport(1280,800);assertEquals("Working",page().locator("#occurrence-displayName").inputValue());
        String storageBefore=unchanged;withRejectedWorkspaceUpdates("NEW.lifecycle_state = 'DEFINITION_DRAFT'",()->{preview();page().locator("#save-occurrences").click();workbench.awaitText("No selected change was committed");assertEquals(storageBefore,storedDocument());assertEquals("Working",page().locator("#occurrence-displayName").inputValue());});
        page().route("**/api/definition-draft/occurrences",route->route.abort());preview();page().locator("#save-occurrences").click();workbench.awaitText("No selected change was committed");assertEquals(unchanged,storedDocument());page().unroute("**/api/definition-draft/occurrences");save();assertEquals(source,draft().path("sourceDocument"));for(var entry:source.properties())assertEquals(entry.getValue(),storedWorkspaceDocument().path(entry.getKey()));
        unchanged=storedDocument();APIResponse csrf=page().request().post(base()+"/api/definition-draft/occurrences/preview",RequestOptions.create().setData(JSON.writeValueAsString(op)).setHeader("Content-Type","application/json").setHeader("Origin",base()).setHeader("If-Match","\"ws-"+storedVersion()+"\""));assertEquals(403,csrf.status());assertEquals(unchanged,storedDocument());op=operation("lesson-math-1");change(op,"id","new-id");assertEquals(409,previewCommand(op).status());assertEquals(unchanged,storedDocument());for(WorkspaceState state:WorkspaceState.values()){if(state==WorkspaceState.DEFINITION_DRAFT)continue;store(state.name(),storedWorkspaceDocument());unchanged=storedDocument();assertEquals(409,previewCommand(operation("lesson-math-1")).status());assertEquals(unchanged,storedDocument());}
    }

    @Test
    void expiredPinEqualExplicitPolicyAndTypedInvalidValuesPreserveExactProvenance() throws Exception {
        ObjectNode doc=fixtures.validAcceptedDocument();ObjectNode sourceLesson=(ObjectNode)doc.path("acceptedBaseline").path("definition").path("lessons").get(0);sourceLesson.put("periodLock","mon-1");String revision=verifier.verify(new ImportDocuments(doc.path("acceptedBaseline").path("definition"),null,null,ImportDocuments.ImportMode.INITIAL_DEFINITION)).definitionRevision();ObjectNode result=(ObjectNode)doc.path("acceptedBaseline").path("result");result.put("inputRevision",revision);ObjectNode scope=JSON.createObjectNode().put("schemaVersion",1).put("schoolId",result.path("schoolId").asString()).put("inputRevision",revision);var ordered=new java.util.ArrayList<JsonNode>();result.path("timetable").path("assignments").forEach(ordered::add);ordered.sort(java.util.Comparator.comparing(row->row.path("lessonId").asString()));ordered.forEach(scope.putArray("assignments")::add);String timetableRevision="sha256:"+java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(CanonicalJson.bytes(scope)));result.put("timetableRevision",timetableRevision);doc.put("definitionRevision",revision).put("timetableRevision",timetableRevision);doc.withObject("acceptedBaseline").withObject("manifest").put("inputRevision",revision).put("timetableRevision",timetableRevision).withArray("locks").addObject().put("lessonId","lesson-math-1").put("periodLockOrigin","ATTEMPT_SCOPED");storeAccepted(doc);workbench.open();open();nav("Occurrence details");form();assertFalse(lesson("lesson-math-1").has("periodLock"));JsonNode source=draft().path("sourceDocument").deepCopy();ObjectNode op=operation("lesson-math-1");change(op,"periodLock","mon-1");assertEquals(200,saveCommand(op).status());assertEquals("mon-1",draft().path("editingContext").path("authoredLocks").path("lesson-math-1").path("periodLock").asString());assertEquals(source,draft().path("sourceDocument"));
        op=operation("lesson-math-1");op.withObject("changes").putObject("teacherId").put("mode","value").putArray("value").add("typed invalid");op.withObject("changes").putObject("preferredRoomIds").put("mode","value").put("value",false);assertEquals(200,saveCommand(op).status());assertEquals(JSON.readTree("[\"typed invalid\"]"),lesson("lesson-math-1").path("teacherId"));assertFalse(lesson("lesson-math-1").path("preferredRoomIds").booleanValue());assertTrue(draft().path("issues").toString().contains("BLOCKING"));assertEquals(source,draft().path("sourceDocument"));
    }

    private void initial(boolean mixed){ObjectNode def=((ObjectNode)fixtures.validAcceptedDocument().path("acceptedBaseline").path("definition")).deepCopy();def.put("catalogVersion",9);def.withArray("teachers").addObject().put("id","teacher-blair").put("displayName","Blair").putArray("qualifiedSubjectIds").add("math");def.putArray("roomAssignments").addObject().put("id","math-alex").put("subjectId","math").put("teacherId","teacher-alex").putArray("allowedRoomIds").add("room-101");if(mixed){ObjectNode row=((ObjectNode)def.path("lessons").get(0)).deepCopy().put("id","imported.math.2").put("displayName","Keep imported name").put("teacherId","teacher-blair");def.withArray("lessons").add(row);}ObjectNode doc=JSON.createObjectNode();doc.set("initialDefinition",def);store("INITIAL_DRAFT",doc);workbench.open();}
    private com.microsoft.playwright.Page page(){return workbench.page();}
    private void open(){page().locator("#open-authoring").click();page().locator("#confirm-authoring").click();workbench.awaitText("Saved school-definition draft");}
    private void nav(String section){page().locator("button[data-section='"+section+"']").click();}
    private void form(){page().locator("#occurrence-form").waitFor();}
    private void value(String field,String value){page().locator("#occurrence-"+field+"-mode").selectOption("value");page().locator("#occurrence-"+field).fill(value);}
    private void preview(){page().locator("#preview-occurrences").click();page().locator("#occurrence-preview").waitFor();}
    private void save(){long version=storedVersion();preview();page().locator("#save-occurrences").click();workbench.expect("document.querySelector('#school-save-status')?.textContent.startsWith('Saved —')");assertEquals(version+1,storedVersion());form();}
    private JsonNode draft(){return storedWorkspaceDocument().path("definitionDraft");}
    private JsonNode definition(){return draft().path("definition");}
    private JsonNode context(String id){return draft().path("editingContext").path("requirements").path(id);}
    private JsonNode lesson(String id){for(JsonNode row:definition().path("lessons"))if(id.equals(row.path("id").asString()))return row;fail("Missing "+id);return null;}
    private ObjectNode operation(String... ids){ObjectNode op=JSON.createObjectNode();var selected=op.putArray("selectedIds");for(String id:ids)selected.add(id);op.putObject("changes");op.putObject("grouping").put("mode","keep");op.putArray("transferRuleIds");return op;}
    private void change(ObjectNode op,String field,String value){op.withObject("changes").putObject(field).put("mode","value").put("value",value);}
    private void mode(ObjectNode op,String field,String mode){op.withObject("changes").putObject(field).put("mode",mode);}
    private String base(){return "http://localhost:"+port;}
    private APIResponse previewCommand(JsonNode op){return post("/api/definition-draft/occurrences/preview",op,null);}
    private APIResponse saveCommand(JsonNode op){APIResponse p=previewCommand(op);assertEquals(200,p.status(),p.text());ObjectNode env=JSON.createObjectNode().put("token",JSON.readTree(p.text()).path("token").asString());env.set("request",op);return post("/api/definition-draft/occurrences",env,null);}
    private APIResponse post(String path,JsonNode body,String version){JsonNode csrf=JSON.readTree(page().request().get(base()+"/api/csrf").text());return page().request().post(base()+path,RequestOptions.create().setData(JSON.writeValueAsString(body)).setHeader("Content-Type","application/json").setHeader("Origin",base()).setHeader("If-Match",version==null?"\"ws-"+storedVersion()+"\"":version).setHeader(csrf.path("headerName").asString(),csrf.path("token").asString()));}
    private void store(String state,JsonNode document){jdbc.sql("UPDATE workspace_aggregate SET lifecycle_state=:state, version=version+1, active_run_id=NULL, document=CAST(:document AS jsonb) WHERE workspace_id=1").param("state",state).param("document",JSON.writeValueAsString(document)).update();}
}
